function CommodityCard({ card, t }) {
  return (
    <article className="interactive-card flex h-full min-w-0 flex-col rounded-xl border border-[#B3C0FF] bg-[#FDFDFE] p-4 sm:p-6"

    >
      <div className="flex items-start justify-between gap-3">
        <div className="flex min-w-0 items-start gap-4">
          <span className="flex h-12 w-12 shrink-0 items-center justify-center rounded-full bg-white"
            style={{
              filter: "drop-shadow(-9px 12px 20px rgba(41, 59, 147, 0.20))"
            }}
          >
            <OilBarrelIcon />
          </span>
          <div className="min-w-0 pt-0.5">
            <p className="Text font-bold leading-tight text-[#293B93]">
              {t(`cards.${card.nameKey}.name`, card.nameFallback)}
            </p>
            <p className="TextSmall mt-0.5 font-normal text-[#999999]">
              {t(`cards.${card.symbolKey}`, card.symbolFallback)}
            </p>
          </div>
        </div>
        <CardSparkline pathD={card.sparkPath} id={card.id} />
      </div>

      <div className=" flex flex-wrap items-baseline gap-6">
        <p className="HeadingH3 font-bold leading-none  text-[#111827]">
          {card.price}
        </p>
        <span className="inline-flex items-center gap-1 TextSmall font-semibold text-[#1AAF5D]">
          {card.change}
          <TrendUpIcon />
        </span>
      </div>

      <div className="mt-3 border-t border-[#D9D9D9] pt-3">
        <div className="flex items-center justify-between gap-4 TextSmall text-[#666B82] font-normal">
          <span className="flex items-center gap-6">
            {t("highLabel", "High")}{" "}
            <span className="font-normal text-[#666B82]">{card.high}</span>
          </span>
          <span className="flex items-center gap-6">
            {t("lowLabel", "Low")}{" "}
            <span className="font-normal text-[#666B82]">{card.low}</span>
          </span>
        </div>
      </div>
    </article>
  );
}

function FeatureItem({ item, t }) {
  const Icon = FEATURE_ICONS[item.icon] || IconEnergyMarkets;

  return (
    <div className="flex min-w-0 items-start gap-q.5 sm:gap-2">
      <span className="flex h-11 w-11 shrink-0 items-center justify-center text-white sm:h-12 sm:w-12">
        <Icon className="h-5 w-5 sm:h-8 sm:w-8" />
      </span>
      <div className="min-w-0 pt-0.5">
        <p className="Text font-bold leading-snug text-[#293B93]">
          {t(`features.${item.key}.title`, item.titleFallback)}
        </p>
        <p className="TextSmall mt-1 font-normal leading-[1.3] text-[#707B95]">
          {t(`features.${item.key}.description`, item.descriptionFallback)}
        </p>
      </div>
    </div>
  );
}

export default function MarketsPopularCommoditiesSection() {
  const t = usePathTranslation("marketsPage.popularCommoditiesSection");

  return (
    <section className="overflow-x-hidden bg-white py-14 md:py-16">
      <div className="container min-w-0 max-w-full">
        <div className="mx-auto max-w-6xl">
          <div className="mx-auto max-w-3xl text-center">
            <h2 className="HeadingH2 text-[#293B93] font-bold">
              {t("title", "Popular Commodities")}
            </h2>
            <p className="Text mx-auto mt-4 font-normal leading-[1.6] text-[#666666] md:mt-5">
              {t(
                "description",
                "Access leading global indices and trade the markets that move the world — with real-time data, advanced tools, and zero friction."
              )}
            </p>
          </div>

          <div className="mt-10 md:mt-12">
            <div className="hidden gap-6 md:grid md:grid-cols-2">
              {COMMODITY_CARDS.map((card) => (
                <CommodityCard key={card.id} card={card} t={t} />
              ))}
            </div>

            <div className="md:hidden">
              <MobilePeekCarousel
                items={COMMODITY_CARDS}
                showArrows
                className="w-full min-w-0"
                trackClassName="-mx-4 px-4 min-w-0"
                slideClassName="!h-auto"
                renderItem={(card) => (
                  <div className="w-full min-w-0">
                    <CommodityCard card={card} t={t} />
                  </div>
                )}
              />
            </div>
          </div>

          <div className="pt-10  md:pt-12">
            <div className="hidden gap-8 lg:grid lg:grid-cols-4 lg:gap-6 xl:gap-10">
              {FEATURE_ITEMS.map((item) => (
                <FeatureItem key={item.key} item={item} t={t} />
              ))}
            </div>

            <div className="grid gap-8 sm:grid-cols-2 lg:hidden">
              {FEATURE_ITEMS.map((item) => (
                <FeatureItem key={item.key} item={item} t={t} />
              ))}
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}
